def build_agent(sandbox):
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    import math

    pos = sandbox.get_agent_position()
    vel = sandbox.get_agent_velocity()
    next_sw = sandbox.get_next_required_switch()
    steps_in_zone = sandbox.get_steps_in_current_zone()
    steps_needed = sandbox.get_steps_required_to_trigger()
    cooldown_remaining = sandbox.get_cooldown_remaining()
    barrier_delay = sandbox.get_barrier_delay_steps()
    bx = sandbox.get_barrier_x()
    triggered = sandbox.get_triggered_switches()

    ZONE_A = {'x': 2.0, 'y': 2.0, 'hw': 0.5, 'hh': 0.5}
    ZONE_B = {'x': 4.95, 'y': 3.2, 'hw': 0.7, 'hh': 0.4}
    ZONE_C = {'x': 8.0, 'y': 2.0, 'hw': 0.5, 'hh': 0.5}
    PLATFORM_ZONE = {'x': 5.5, 'y': 3.5, 'hw': 1.0, 'hh': 0.5}

    def in_zone(zone):
        agent_x, agent_y = pos
        zone_x, zone_y, zone_hw, zone_hh = zone['x'], zone['y'], zone['hw'], zone['hh']
        return (zone_x - zone_hw + 0.2 <= agent_x <= zone_x + zone_hw - 0.2) and \
               (zone_y - zone_hh + 0.2 <= agent_y <= zone_y + zone_hh - 0.2)

    def distance_to(target_x, target_y):
        return math.hypot(pos[0] - target_x, pos[1] - target_y)

    fx = 0.0
    fy = 0.0

    if next_sw == 'A':
        if cooldown_remaining > 0:
            pass
        else:
            if in_zone(ZONE_A):
                if steps_in_zone < steps_needed:
                    dx = ZONE_A['x'] - pos[0]
                    dy = ZONE_A['y'] - pos[1]
                    dist = math.hypot(dx, dy)
                    if dist > 0.05:
                        dir_x = dx / dist
                        dir_y = dy / dist
                        fx = 1.0 * dir_x
                        fy = 1.0 * dir_y
                    else:
                        fx = 0.0
                        fy = 0.0
                else:
                    pass
            else:
                target_x, target_y = ZONE_A['x'], ZONE_A['y']
                dx = target_x - pos[0]
                dy = target_y - pos[1]
                dist = math.hypot(dx, dy)
                if dist > 0.1:
                    dir_x = dx / dist
                    dir_y = dy / dist
                    fx = 1.0 * dir_x
                    fy = 1.0 * dir_y
                else:
                    fx = 0.0
                    fy = 0.0
    elif next_sw == 'B':
        if cooldown_remaining > 0:
            pass
        else:
            if barrier_delay > 0:
                pass
            else:
                if in_zone(PLATFORM_ZONE):
                    target_x, target_y = ZONE_B['x'], ZONE_B['y']
                    dx = target_x - pos[0]
                    dy = target_y - pos[1]
                    dist = math.hypot(dx, dy)
                    if dist > 0.1:
                        dir_x = dx / dist
                        dir_y = dy / dist
                        fx = 5.0 * dir_x
                        fy = 5.0 * dir_y
                    else:
                        fx = 0.0
                        fy = 0.0
                else:
                    target_x, target_y = PLATFORM_ZONE['x'], PLATFORM_ZONE['y']
                    dx = target_x - pos[0]
                    dy = target_y - pos[1]
                    dist = math.hypot(dx, dy)
                    if dist > 0.1:
                        dir_x = dx / dist
                        dir_y = dy / dist
                        fx = 5.0 * dir_x
                        fy = 5.0 * dir_y
                    else:
                        fx = 0.0
                        fy = 0.0
    elif next_sw == 'C':
        if cooldown_remaining > 0:
            pass
        else:
            if 'B' in triggered:
                if in_zone(ZONE_C):
                    if steps_in_zone < steps_needed:
                        dx = ZONE_C['x'] - pos[0]
                        dy = ZONE_C['y'] - pos[1]
                        dist = math.hypot(dx, dy)
                        if dist > 0.05:
                            dir_x = dx / dist
                            dir_y = dy / dist
                            fx = 1.0 * dir_x
                            fy = 1.0 * dir_y
                        else:
                            fx = 0.0
                            fy = 0.0
                    else:
                        pass
                else:
                    target_x, target_y = ZONE_C['x'], ZONE_C['y']
                    dx = target_x - pos[0]
                    dy = target_y - pos[1]
                    dist = math.hypot(dx, dy)
                    if dist > 0.1:
                        dir_x = dx / dist
                        dir_y = dy / dist
                        fx = 5.0 * dir_x
                        fy = 5.0 * dir_y
                    else:
                        fx = 0.0
                        fy = 0.0
            else:
                target_x, target_y = PLATFORM_ZONE['x'], PLATFORM_ZONE['y']
                dx = target_x - pos[0]
                dy = target_y - pos[1]
                dist = math.hypot(dx, dy)
                if dist > 0.1:
                    dir_x = dx / dist
                    dir_y = dy / dist
                    fx = 5.0 * dir_x
                    fy = 5.0 * dir_y
                else:
                    fx = 0.0
                    fy = 0.0

    fx = max(min(fx, 50.0), -50.0)
    fy = max(min(fy, 50.0), -50.0)

    current_speed = math.hypot(vel[0], vel[1])
    if current_speed > 0.08:
        fx = 0.0
        fy = 0.0

    sandbox.apply_agent_force(fx, fy)
